  3	public final class BellmanFord {
  4	    private static final int LEGACY_UNREACHABLE_DISTANCE = 100_000_000;
  5	    private static final int[] NEGATIVE_CYCLE_RESULT = {-1};
  6	
  7	    private BellmanFord() {
  8	    }
  9	
 10	    public static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
 11	        return shortestPaths(vertices, edgeData, source);
 12	    }
 13	
 14	    public static int[] shortestPaths(int vertices, int[][] edgeData, int source) {
 15	        ShortestPathResult result = computeShortestPaths(WeightedGraph.from(vertices, edgeData), source);
 16	        if (result.hasNegativeCycle()) {
 17	            return NEGATIVE_CYCLE_RESULT.clone();
 18	        }
 19	        return result.distances();
 20	    }
 21	
 22	    public static ShortestPathResult computeShortestPaths(WeightedGraph graph, int source) {
 23	        validateSource(source, graph.vertices());
 24	        List<WeightedEdge> edges = graph.edges();
 25	        DistanceState state = DistanceState.fromSource(graph.vertices(), source);
 26	
 27	        for (int pass = 0; pass < graph.vertices() - 1; pass++) {
 28	            boolean updated = false;
 29	
 30	            for (WeightedEdge edge : edges) {
 31	                updated |= relax(edge, state);
 32	            }
 33	
 34	            if (!updated) {
 35	                return ShortestPathResult.success(
 36	                    state.toLegacyDistances(),
 37	                    state.reachableVertices()
 38	                );
 39	            }
 40	        }
 41	
 42	        if (hasNegativeCycle(edges, state)) {
 43	            return ShortestPathResult.negativeCycle();
 44	        }
 45	
 46	        return ShortestPathResult.success(
 47	            state.toLegacyDistances(),
 48	            state.reachableVertices()
 49	        );
 50	    }
 51	
 52	    private static boolean relax(WeightedEdge edge, DistanceState state) {
 53	        if (!state.isReachable(edge.from())) {
 54	            return false;
 55	        }
 56	
 57	        long candidateDistance = Math.addExact(state.distanceTo(edge.from()), edge.weight());
 58	        if (state.isReachable(edge.to()) && candidateDistance >= state.distanceTo(edge.to())) {
 59	            return false;
 60	        }
 61	
 62	        state.update(edge.to(), candidateDistance);
 63	        return true;
 64	    }
 65	
 66	    private static boolean hasNegativeCycle(List<WeightedEdge> edges, DistanceState state) {
 67	        for (WeightedEdge edge : edges) {
 68	            if (!state.isReachable(edge.from())) {
 69	                continue;
 70	            }
 71	
 72	            long candidateDistance = Math.addExact(state.distanceTo(edge.from()), edge.weight());
 73	            if (!state.isReachable(edge.to()) || candidateDistance < state.distanceTo(edge.to())) {
 74	                return true;
 75	            }
 76	        }
 77	        return false;
 78	    }
 79	
 80	    private static void validateSource(int source, int vertices) {
 81	        validateVertex(source, vertices, "source");
 82	    }
 83	
 84	    private static void validateVertex(int vertex, int vertices, String label) {
 85	        if (vertex < 0 || vertex >= vertices) {
 86	            throw new IllegalArgumentException(label + " must be within the vertex range");
 87	        }
 88	    }
 89	
 90	    private static final class DistanceState {
 91	        private final long[] distances;
 92	        private final boolean[] reachable;
 93	
 94	        private DistanceState(long[] distances, boolean[] reachable) {
 95	            this.distances = distances;
 96	            this.reachable = reachable;
 97	        }
 98	
 99	        private static DistanceState fromSource(int vertices, int source) {
100	            long[] distances = new long[vertices];
101	            boolean[] reachable = new boolean[vertices];
102	            reachable[source] = true;
103	            return new DistanceState(distances, reachable);
104	        }
105	
106	        private boolean isReachable(int vertex) {
107	            return reachable[vertex];
108	        }
109	
110	        private long distanceTo(int vertex) {
111	            return distances[vertex];
112	        }
113	
114	        private void update(int vertex, long distance) {
115	            distances[vertex] = distance;
116	            reachable[vertex] = true;
117	        }
118	
119	        private int[] toLegacyDistances() {
120	            int[] legacyDistances = new int[distances.length];
121	            for (int vertex = 0; vertex < distances.length; vertex++) {
122	                legacyDistances[vertex] = reachable[vertex]
123	                    ? toIntExact(distances[vertex])
124	                    : LEGACY_UNREACHABLE_DISTANCE;
125	            }
126	            return legacyDistances;
127	        }
128	
129	        private boolean[] reachableVertices() {
130	            return reachable.clone();
131	        }
132	
133	        private int toIntExact(long distance) {
134	            if (distance < Integer.MIN_VALUE || distance > Integer.MAX_VALUE) {
135	                throw new ArithmeticException("shortest path distance exceeds int range");
136	            }
137	            return (int) distance;
138	        }
139	    }
140	}

